<?php $breakdown=json_decode($r->breakdown_json,true)?:[];$origin=json_decode($r->origin_json,true)?:[];$s=new DeliveryService();$items=$s->sql('SELECT tracking FROM cdb_delivery_items WHERE request_id=?',[$r->id])->fetchAll(PDO::FETCH_COLUMN); ?>
<section class="sl-card col g16"><div class="row between wrap g8"><h2 class="sl-ct">Delivery #<?= (int)$r->id ?></h2><span class="sl-badge"><?= h(ucfirst($r->state)) ?></span></div>
<div class="grid cols2"><div class="col g8"><span class="up">Destination</span><b><?= h($r->address) ?></b><span><?= h($r->contact_name.' · '.$r->contact_phone) ?></span><?php if($r->instructions): ?><p><?= h($r->instructions) ?></p><?php endif; ?><a class="sl-btn ghost" href="https://www.google.com/maps/dir/?api=1&amp;destination=<?= h(rawurlencode($r->lat.','.$r->lng)) ?>&amp;destination_place_id=<?= h(rawurlencode($r->place_id)) ?>&amp;travelmode=driving" target="_blank" rel="noopener">Navigate with Google Maps</a></div>
<div class="col g8"><span class="up">Approved delivery fee</span><b class="sl-title"><?= h(dl_money((int)$r->amount_cents,$r->currency)) ?></b><span><?= h($r->pricing_mode) ?> · <?= number_format($r->distance_m/1000,2) ?> road km · <?= count(json_decode($r->parcel_json,true)?:[]) ?> parcel(s)</span><span class="mut"><?= h($breakdown['zone_name']??'') ?></span><span class="mut">From <?= h($origin['address']??'') ?></span><span class="sm">Base: <?= h(dl_money((int)($breakdown['base_cents']??0),$r->currency)) ?> · Variable: <?= h(dl_money((int)($breakdown['variable_cents']??0),$r->currency)) ?> · Minimum: <?= h(dl_money((int)($breakdown['minimum_cents']??0),$r->currency)) ?></span><span class="sm"><?= $r->fee_collected?'Delivery fee recorded as collected':'Delivery fee due on delivery' ?></span></div></div>
<?php if($items): ?><p class="mono sm"><?= h(implode(', ',$items)) ?></p><?php endif; ?>
<?php if($r->proof_photo): ?><a href="delivery_proof.php?id=<?= (int)$r->id ?>" class="sl-btn ghost" target="_blank" rel="noopener">View delivery photo</a><p>Received by <?= h($r->receiver_name) ?> · <?= h(sl_date($r->completed_at,'M j, H:i')) ?></p><?php endif; ?>
<?php if($d['events']): ?><div class="sl-tl"><?php foreach($d['events'] as $event): ?><div class="sl-tl-i"><b><?= h(ucfirst($event->state)) ?></b><span><?= h($event->note) ?></span><small class="mut"><?= h(sl_date($event->created_at,'M j, H:i')) ?></small></div><?php endforeach; ?></div><?php endif; ?></section>
